parameters.text:
=Create a lightweight, story-level test plan for the following Jira user story and its Acceptance Criteria.

Jira Story / Acceptance Criteria:
{{ $json.chatInput }}

=Based on the test plan below, generate detailed test scenarios for the same Jira story.

Original Story / Acceptance Criteria:
{{ $('When chat message received').item.json.chatInput }}

Test Plan - Scope (In Scope):
{{ JSON.stringify($json.output.scope.inScope) }}

Test Plan - Test Approach:
{{ JSON.stringify($json.output.testApproach) }}

parameters.jsCode:
const plan = $('Test Plan Agent').item.json.output;
const scenarioOut = $input.item.json.output;
const scenarios = scenarioOut.scenarios || [];

let md = `## Test Plan

`;
md += `**In Scope:**
` + (plan.scope.inScope || []).map(s => `- ${s}`).join('
') + `

`;
md += `**Out of Scope:**
` + (plan.scope.outOfScope || []).map(s => `- ${s}`).join('
') + `

`;
md += `**Test Approach:**
` + (plan.testApproach || []).map(a => `- ${a.type}: ${a.description}`).join('
') + `

`;
md += `**Risks & Mitigations:**
` + (plan.risks || []).map(r => `- Risk: ${r.risk} | Mitigation: ${r.mitigation}`).join('
') + `

`;
md += `**Entry Criteria:**
` + (plan.entryCriteria || []).map(s => `- ${s}`).join('
') + `

`;
md += `**Exit Criteria:**
` + (plan.exitCriteria || []).map(s => `- ${s}`).join('
') + `

`;
md += `**Environment:** ${plan.environmentAndData.environment}
`;
md += `**Test Data Needed:**
` + (plan.environmentAndData.testData || []).map(s => `- ${s}`).join('
') + `

`;

md += `## Test Scenarios

`;
for (const s of scenarios) {
  md += `- [${s.id}] (${s.category} / ${s.priority}) ${s.title} -- ref: ${s.relatedAC}
`;
}

return [{
  json: {
    output: md,
    testPlan: plan,
    scenarios
  }
}];
